    gettimeofday(&func_args->t1, NULL);

    const float* bptr = b;
    float* aptr = a;

    for (int nl = 0; nl < iterations; nl++) {
        int i = 0;
        while (i < LEN_1D) {
            size_t vl = __riscv_vsetvl_e32m8((size_t)(LEN_1D - i));

            vfloat32m8_t vb = __riscv_vle32_v_f32m8(bptr + i, vl);
            vfloat32m8_t va = __riscv_vle32_v_f32m8(aptr + i, vl);

            vbool4_t mask = __riscv_vmfgt_vf_f32m8_b4(vb, (float)0.0f, vl);
            va = __riscv_vmerge_vvm_f32m8(va, vb, mask, vl);

            __riscv_vse32_v_f32m8(aptr + i, va, vl);
            i += (int)vl;
        }

        dummy(a, b, c, d, e, aa, bb, cc, 0.);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

